package db

import (
	"context"
	"embed"
	"encoding/json"
	"fmt"
	"io/fs"
	"path"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"
)

// The Quran's printed topical index — the alphabetical subject index bound into
// the back of Quran, The Final Testament (see
// migrations/031_quran_topic_index.sql). Seeded from
// db/seeds/quran_topic_index_<lang>.json, generated by
// scripts/topic_index/build.mjs from masjidtucson.org's HTML pages.
//
// Verse numbers here are 1-based, as printed. public.verses.verse_index is
// 0-based; do not join the two without converting.

// Wildcard embed so adding an index edition needs no code change here, matching
// the pattern db/site.go uses for the site document seeds.
//
//go:embed seeds/quran_topic_index_*.json
var topicIndexSeeds embed.FS

// ── Seed ────────────────────────────────────────────────────────────────────

type topicSeedFile struct {
	Metadata map[string]string `json:"metadata"`
	Entries  []topicSeedEntry  `json:"entries"`
}

type topicSeedEntry struct {
	Letter     string              `json:"letter"`
	Title      string              `json:"title"`
	SortKey    string              `json:"sort_key"`
	Slug       string              `json:"slug"`
	Position   int                 `json:"position"`
	CrossRefs  []string            `json:"cross_refs"`
	Refs       []topicSeedRef      `json:"refs"`
	Subentries []topicSeedSubentry `json:"subentries"`
}

type topicSeedSubentry struct {
	Label    string         `json:"label"`
	Position int            `json:"position"`
	Refs     []topicSeedRef `json:"refs"`
}

type topicSeedRef struct {
	ChapterNumber int    `json:"chapter_number"`
	VerseStart    int    `json:"verse_start"`
	VerseEnd      int    `json:"verse_end"`
	Display       string `json:"display"`
	Position      int    `json:"position"`
}

// langFromTopicSeedName pulls "en" out of "seeds/quran_topic_index_en.json".
func langFromTopicSeedName(name string) string {
	base := strings.TrimSuffix(path.Base(name), ".json")
	return strings.TrimPrefix(base, "quran_topic_index_")
}

// SeedTopicIndex loads every embedded index edition, replacing all rows for each
// language present. Full-replace is the update path: regenerate the JSON, re-run
// the seed. Returns the number of entries written.
//
// Three batches inside one transaction, because each level needs the ids the
// previous one returned: entries, then sub-entries, then references.
func (db *DB) SeedTopicIndex(ctx context.Context) (int, error) {
	defer observe("seed_topic_index", time.Now())

	files, err := fs.Glob(topicIndexSeeds, "seeds/quran_topic_index_*.json")
	if err != nil {
		return 0, fmt.Errorf("glob topic index seeds: %w", err)
	}
	if len(files) == 0 {
		return 0, fmt.Errorf("no quran_topic_index_*.json seeds embedded")
	}

	tx, err := db.Pool.Begin(ctx)
	if err != nil {
		return 0, err
	}
	defer func() { _ = tx.Rollback(ctx) }()

	written := 0
	for _, file := range files {
		lang := langFromTopicSeedName(file)
		if lang == "" {
			return 0, fmt.Errorf("cannot derive lang from seed name %q", file)
		}

		raw, err := topicIndexSeeds.ReadFile(file)
		if err != nil {
			return 0, fmt.Errorf("read %s: %w", file, err)
		}
		var parsed topicSeedFile
		if err := json.Unmarshal(raw, &parsed); err != nil {
			return 0, fmt.Errorf("parse %s: %w", file, err)
		}
		if len(parsed.Entries) == 0 {
			return 0, fmt.Errorf("%s contains no entries", file)
		}

		// Cascades to sub-entries and refs.
		if _, err := tx.Exec(ctx,
			`DELETE FROM topic_index_entries WHERE lang = $1`, lang,
		); err != nil {
			return 0, fmt.Errorf("clear topic index for %q: %w", lang, err)
		}

		if err := seedTopicEntries(ctx, tx, lang, parsed.Entries); err != nil {
			return 0, err
		}
		written += len(parsed.Entries)
	}

	if err := tx.Commit(ctx); err != nil {
		return 0, err
	}
	return written, nil
}

func seedTopicEntries(ctx context.Context, tx pgx.Tx, lang string, entries []topicSeedEntry) error {
	// Level 1: entries. subentry_text denormalizes the sub-entry labels so
	// search_tsv can weight them without a join.
	entryBatch := &pgx.Batch{}
	for _, e := range entries {
		labels := make([]string, 0, len(e.Subentries))
		for _, s := range e.Subentries {
			if s.Label != "" {
				labels = append(labels, s.Label)
			}
		}
		crossRefs := e.CrossRefs
		if crossRefs == nil {
			crossRefs = []string{}
		}
		entryBatch.Queue(
			`INSERT INTO topic_index_entries
			   (lang, letter, title, sort_key, slug, position, cross_refs, subentry_text)
			 VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
			 ON CONFLICT (lang, sort_key) DO UPDATE SET
			   letter = EXCLUDED.letter, title = EXCLUDED.title, slug = EXCLUDED.slug,
			   position = EXCLUDED.position, cross_refs = EXCLUDED.cross_refs,
			   subentry_text = EXCLUDED.subentry_text, updated_at = now()
			 RETURNING id`,
			lang, e.Letter, e.Title, e.SortKey, e.Slug, e.Position,
			crossRefs, strings.Join(labels, " "),
		)
	}

	entryIDs := make([]int, len(entries))
	entryResults := tx.SendBatch(ctx, entryBatch)
	for i := range entries {
		if err := entryResults.QueryRow().Scan(&entryIDs[i]); err != nil {
			_ = entryResults.Close()
			return fmt.Errorf("insert topic entry %q (%s): %w", entries[i].Title, lang, err)
		}
	}
	if err := entryResults.Close(); err != nil {
		return fmt.Errorf("close topic entry batch (%s): %w", lang, err)
	}

	// Level 2: sub-entries. Keep a parallel index so the ids can be matched back
	// to the (entry, sub-entry) pair when queueing references.
	type subKey struct{ entry, sub int }
	subBatch := &pgx.Batch{}
	subOrder := make([]subKey, 0)
	for i, e := range entries {
		for j, s := range e.Subentries {
			subBatch.Queue(
				`INSERT INTO topic_index_subentries (entry_id, label, position)
				 VALUES ($1, $2, $3)
				 ON CONFLICT (entry_id, position) DO UPDATE SET label = EXCLUDED.label
				 RETURNING id`,
				entryIDs[i], s.Label, s.Position,
			)
			subOrder = append(subOrder, subKey{entry: i, sub: j})
		}
	}

	subIDs := make(map[subKey]int, len(subOrder))
	if len(subOrder) > 0 {
		subResults := tx.SendBatch(ctx, subBatch)
		for _, key := range subOrder {
			var id int
			if err := subResults.QueryRow().Scan(&id); err != nil {
				_ = subResults.Close()
				return fmt.Errorf("insert topic sub-entry for %q (%s): %w", entries[key.entry].Title, lang, err)
			}
			subIDs[key] = id
		}
		if err := subResults.Close(); err != nil {
			return fmt.Errorf("close topic sub-entry batch (%s): %w", lang, err)
		}
	}

	// Level 3: references. subentry_id is NULL for entry-level references.
	refBatch := &pgx.Batch{}
	refCount := 0
	queueRef := func(entryID int, subentryID *int, r topicSeedRef) {
		refBatch.Queue(
			`INSERT INTO topic_index_refs
			   (entry_id, subentry_id, chapter_number, verse_start, verse_end, display, position)
			 VALUES ($1, $2, $3, $4, $5, $6, $7)
			 ON CONFLICT (entry_id, COALESCE(subentry_id, 0), position) DO UPDATE SET
			   chapter_number = EXCLUDED.chapter_number, verse_start = EXCLUDED.verse_start,
			   verse_end = EXCLUDED.verse_end, display = EXCLUDED.display`,
			entryID, subentryID, r.ChapterNumber, r.VerseStart, r.VerseEnd, r.Display, r.Position,
		)
		refCount++
	}

	for i, e := range entries {
		for _, r := range e.Refs {
			queueRef(entryIDs[i], nil, r)
		}
		for j, s := range e.Subentries {
			subID := subIDs[subKey{entry: i, sub: j}]
			for _, r := range s.Refs {
				queueRef(entryIDs[i], &subID, r)
			}
		}
	}

	if refCount > 0 {
		refResults := tx.SendBatch(ctx, refBatch)
		for i := 0; i < refCount; i++ {
			if _, err := refResults.Exec(); err != nil {
				_ = refResults.Close()
				return fmt.Errorf("insert topic reference (%s): %w", lang, err)
			}
		}
		if err := refResults.Close(); err != nil {
			return fmt.Errorf("close topic reference batch (%s): %w", lang, err)
		}
	}

	return nil
}

// ── Row types ───────────────────────────────────────────────────────────────

// TopicEntryRow is one row of topic_index_entries, without its children.
type TopicEntryRow struct {
	ID        int      `db:"id"`
	Lang      string   `db:"lang"`
	Letter    string   `db:"letter"`
	Title     string   `db:"title"`
	Slug      string   `db:"slug"`
	Position  int      `db:"position"`
	CrossRefs []string `db:"cross_refs"`
}

// TopicSubentryRow is one row of topic_index_subentries.
type TopicSubentryRow struct {
	ID       int    `db:"id"`
	EntryID  int    `db:"entry_id"`
	Label    string `db:"label"`
	Position int    `db:"position"`
}

// TopicRefRow is one verse citation. VerseStart == VerseEnd for a single verse;
// both are 1-based, and 0 means the Basmalah.
type TopicRefRow struct {
	EntryID       int    `db:"entry_id"`
	SubentryID    *int   `db:"subentry_id"`
	ChapterNumber int    `db:"chapter_number"`
	VerseStart    int    `db:"verse_start"`
	VerseEnd      int    `db:"verse_end"`
	Display       string `db:"display"`
	Position      int    `db:"position"`
}

// TopicIndexSubentry is a sub-entry with its own references attached.
type TopicIndexSubentry struct {
	TopicSubentryRow
	Refs []TopicRefRow
}

// TopicIndexEntry is an entry with its references and sub-entries attached, in
// printed order. Score and Headline are populated only by SearchTopicIndex.
type TopicIndexEntry struct {
	TopicEntryRow
	Refs       []TopicRefRow
	Subentries []TopicIndexSubentry
	Score      float32
	Headline   string
}

// TopicLetterCount is one bucket of the A-Z rail.
type TopicLetterCount struct {
	Letter string `db:"letter"`
	Count  int    `db:"count"`
}

const topicEntryCols = `e.id, e.lang, e.letter, e.title, e.slug, e.position, e.cross_refs`

// ── Reads ───────────────────────────────────────────────────────────────────

// TopicIndexByLetter returns one letter of the index in printed order, with
// sub-entries and references attached, plus the total for that letter.
func (db *DB) TopicIndexByLetter(
	ctx context.Context,
	lang, letter string,
	limit, offset int,
) ([]TopicIndexEntry, int, error) {
	defer observe("topic_index_by_letter", time.Now())

	rows, err := db.Pool.Query(ctx, `
        SELECT `+topicEntryCols+`
        FROM   topic_index_entries e
        WHERE  e.lang = $1 AND e.letter = $2
        ORDER  BY e.position
        LIMIT  $3 OFFSET $4
    `, lang, letter, limit, offset)
	if err != nil {
		return nil, 0, err
	}
	defer rows.Close()

	entryRows, err := pgx.CollectRows(rows, pgx.RowToStructByName[TopicEntryRow])
	if err != nil {
		return nil, 0, err
	}

	var total int
	if err := db.Pool.QueryRow(ctx,
		`SELECT COUNT(*) FROM topic_index_entries WHERE lang = $1 AND letter = $2`,
		lang, letter,
	).Scan(&total); err != nil {
		return nil, 0, err
	}

	entries, err := db.hydrateTopicEntries(ctx, entryRows)
	if err != nil {
		return nil, 0, err
	}
	return entries, total, nil
}

// TopicIndexLetterCounts returns the populated letters and their entry counts.
// The printed index has no X, so the rail must not assume all 26 exist.
func (db *DB) TopicIndexLetterCounts(ctx context.Context, lang string) ([]TopicLetterCount, error) {
	defer observe("topic_index_letter_counts", time.Now())

	rows, err := db.Pool.Query(ctx, `
        SELECT letter, COUNT(*)::int AS count
        FROM   topic_index_entries
        WHERE  lang = $1
        GROUP  BY letter
        ORDER  BY letter
    `, lang)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	return pgx.CollectRows(rows, pgx.RowToStructByName[TopicLetterCount])
}

// TopicIndexEntryBySlug returns a single entry, for deep links and for resolving
// a cross-reference to its target.
func (db *DB) TopicIndexEntryBySlug(ctx context.Context, lang, slug string) (*TopicIndexEntry, error) {
	defer observe("topic_index_entry_by_slug", time.Now())

	rows, err := db.Pool.Query(ctx, `
        SELECT `+topicEntryCols+`
        FROM   topic_index_entries e
        WHERE  e.lang = $1 AND e.slug = $2
    `, lang, slug)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	entryRows, err := pgx.CollectRows(rows, pgx.RowToStructByName[TopicEntryRow])
	if err != nil {
		return nil, err
	}
	if len(entryRows) == 0 {
		return nil, nil
	}

	entries, err := db.hydrateTopicEntries(ctx, entryRows)
	if err != nil {
		return nil, err
	}
	return &entries[0], nil
}

// SearchTopicIndex searches entry titles, sub-entry labels and cross-references.
//
// Two legs, unioned: full-text over search_tsv, and a trigram fallback that only
// fires when the full-text leg found nothing — the same UNION ALL ... WHERE NOT
// EXISTS shape db/search.go and db/site.go use. Both trigram operators are
// applied for the reasons documented in db/site.go: similarity() dilutes a short
// typo against a long haystack, word_similarity()'s higher default threshold
// misses a within-word typo, and one gin_trgm_ops index serves both.
//
// LIMIT/OFFSET are applied in the ranked CTE before ts_headline, so highlighting
// only runs on the returned page rather than on all 200 candidates.
func (db *DB) SearchTopicIndex(
	ctx context.Context,
	query, lang string,
	limit, offset int,
) ([]TopicIndexEntry, error) {
	defer observe("search_topic_index", time.Now())

	rows, err := db.Pool.Query(ctx, `
        WITH
          tsq AS (
            SELECT
              CASE
                WHEN $1 ~ '^[A-Za-z]+$'
                THEN to_tsquery('simple', lower($1) || ':*')
                ELSE websearch_to_tsquery('simple', $1)
              END AS q
          ),
          fts AS MATERIALIZED (
            SELECT e.id, e.lang, e.letter, e.title, e.slug, e.position, e.cross_refs,
                   e.subentry_text,
                   ts_rank_cd(e.search_tsv, tsq.q)::real AS score
            FROM   topic_index_entries e CROSS JOIN tsq
            WHERE  e.search_tsv @@ tsq.q
              AND  ($2::text IS NULL OR e.lang = $2::text)
            ORDER  BY score DESC
            LIMIT  200
          ),
          trgm AS (
            SELECT e.id, e.lang, e.letter, e.title, e.slug, e.position, e.cross_refs,
                   e.subentry_text,
                   GREATEST(similarity(e.fuzzy_text, $1), word_similarity($1, e.fuzzy_text))::real AS score
            FROM   topic_index_entries e
            WHERE  NOT EXISTS (SELECT 1 FROM fts)
              AND  (e.fuzzy_text % $1 OR $1 <% e.fuzzy_text)
              AND  ($2::text IS NULL OR e.lang = $2::text)
            ORDER  BY score DESC
            LIMIT  50
          ),
          ranked AS (
            SELECT * FROM (SELECT * FROM fts UNION ALL SELECT * FROM trgm) u
            ORDER  BY score DESC, position
            LIMIT  $3 OFFSET $4
          )
        SELECT r.id, r.lang, r.letter, r.title, r.slug, r.position, r.cross_refs, r.score,
               ts_headline(
                 'simple', r.title || ' ' || r.subentry_text, tsq.q,
                 'MaxWords=20,MinWords=8,MaxFragments=2,StartSel=<b>,StopSel=</b>'
               ) AS headline
        FROM   ranked r CROSS JOIN tsq
        ORDER  BY r.score DESC, r.position
    `, query, nullableLang(lang), limit, offset)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	type hitRow struct {
		TopicEntryRow
		Score    float32 `db:"score"`
		Headline string  `db:"headline"`
	}
	hits, err := pgx.CollectRows(rows, pgx.RowToStructByName[hitRow])
	if err != nil {
		return nil, err
	}

	entryRows := make([]TopicEntryRow, len(hits))
	for i, h := range hits {
		entryRows[i] = h.TopicEntryRow
	}
	entries, err := db.hydrateTopicEntries(ctx, entryRows)
	if err != nil {
		return nil, err
	}
	for i := range entries {
		entries[i].Score = hits[i].Score
		entries[i].Headline = hits[i].Headline
	}
	return entries, nil
}

// CountSearchTopicIndex counts full-text matches only. The trigram fallback is
// excluded on purpose: it fires only when the full-text leg is empty, in which
// case the caller already has every hit on one page.
func (db *DB) CountSearchTopicIndex(ctx context.Context, query, lang string) (int, error) {
	defer observe("count_search_topic_index", time.Now())

	var total int
	err := db.Pool.QueryRow(ctx, `
        WITH tsq AS (
          SELECT
            CASE
              WHEN $1 ~ '^[A-Za-z]+$'
              THEN to_tsquery('simple', lower($1) || ':*')
              ELSE websearch_to_tsquery('simple', $1)
            END AS q
        )
        SELECT COUNT(*)::int
        FROM   topic_index_entries e CROSS JOIN tsq
        WHERE  e.search_tsv @@ tsq.q
          AND  ($2::text IS NULL OR e.lang = $2::text)
    `, query, nullableLang(lang)).Scan(&total)
	return total, err
}

// TopicIndexForVerse returns the entries that cite a verse, so a verse can show
// which topics it belongs to. Ranges are matched inclusively.
func (db *DB) TopicIndexForVerse(
	ctx context.Context,
	lang string,
	chapter, verse int,
) ([]TopicIndexEntry, error) {
	defer observe("topic_index_for_verse", time.Now())

	rows, err := db.Pool.Query(ctx, `
        SELECT DISTINCT `+topicEntryCols+`
        FROM   topic_index_entries e
        JOIN   topic_index_refs r ON r.entry_id = e.id
        WHERE  ($1::text IS NULL OR e.lang = $1::text)
          AND  r.chapter_number = $2
          AND  r.verse_start <= $3
          AND  r.verse_end   >= $3
        ORDER  BY e.letter, e.position
    `, nullableLang(lang), chapter, verse)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	entryRows, err := pgx.CollectRows(rows, pgx.RowToStructByName[TopicEntryRow])
	if err != nil {
		return nil, err
	}
	return db.hydrateTopicEntries(ctx, entryRows)
}

// ── Hydration ───────────────────────────────────────────────────────────────

// hydrateTopicEntries attaches sub-entries and references to a page of entries.
// Two queries over the whole page rather than two per entry — the letter with the
// most entries is S at 186, which would otherwise be 372 round trips.
func (db *DB) hydrateTopicEntries(
	ctx context.Context,
	entryRows []TopicEntryRow,
) ([]TopicIndexEntry, error) {
	entries := make([]TopicIndexEntry, len(entryRows))
	if len(entryRows) == 0 {
		return entries, nil
	}

	ids := make([]int, len(entryRows))
	byID := make(map[int]*TopicIndexEntry, len(entryRows))
	for i, row := range entryRows {
		entries[i] = TopicIndexEntry{
			TopicEntryRow: row,
			Refs:          []TopicRefRow{},
			Subentries:    []TopicIndexSubentry{},
		}
		ids[i] = row.ID
		byID[row.ID] = &entries[i]
	}

	subRows, err := db.Pool.Query(ctx, `
        SELECT id, entry_id, label, position
        FROM   topic_index_subentries
        WHERE  entry_id = ANY($1::int[])
        ORDER  BY entry_id, position
    `, ids)
	if err != nil {
		return nil, err
	}
	subs, err := pgx.CollectRows(subRows, pgx.RowToStructByName[TopicSubentryRow])
	subRows.Close()
	if err != nil {
		return nil, err
	}

	subByID := make(map[int]*TopicIndexSubentry, len(subs))
	for _, s := range subs {
		entry, ok := byID[s.EntryID]
		if !ok {
			continue
		}
		entry.Subentries = append(entry.Subentries, TopicIndexSubentry{
			TopicSubentryRow: s,
			Refs:             []TopicRefRow{},
		})
		subByID[s.ID] = &entry.Subentries[len(entry.Subentries)-1]
	}

	refRows, err := db.Pool.Query(ctx, `
        SELECT entry_id, subentry_id, chapter_number, verse_start, verse_end, display, position
        FROM   topic_index_refs
        WHERE  entry_id = ANY($1::int[])
        ORDER  BY entry_id, subentry_id NULLS FIRST, position
    `, ids)
	if err != nil {
		return nil, err
	}
	refs, err := pgx.CollectRows(refRows, pgx.RowToStructByName[TopicRefRow])
	refRows.Close()
	if err != nil {
		return nil, err
	}

	for _, r := range refs {
		if r.SubentryID != nil {
			if sub, ok := subByID[*r.SubentryID]; ok {
				sub.Refs = append(sub.Refs, r)
			}
			continue
		}
		if entry, ok := byID[r.EntryID]; ok {
			entry.Refs = append(entry.Refs, r)
		}
	}

	return entries, nil
}

// nullableLang turns an empty lang into a SQL NULL, so the callers' `$n IS NULL
// OR lang = $n` predicates mean "every edition". Mirrors how db/search.go treats
// a nil langs slice.
func nullableLang(lang string) *string {
	if lang == "" {
		return nil
	}
	return &lang
}

// FetchTopicIndexLangs returns the index editions that actually have rows, for
// the handler's language validation. Mirrors FetchSiteLangs in db/site.go.
func (db *DB) FetchTopicIndexLangs(ctx context.Context) (map[string]bool, error) {
	defer observe("fetch_topic_index_langs", time.Now())

	rows, err := db.Pool.Query(ctx, `SELECT DISTINCT lang FROM topic_index_entries`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	out := map[string]bool{}
	for rows.Next() {
		var lang string
		if err := rows.Scan(&lang); err != nil {
			return nil, err
		}
		out[lang] = true
	}
	return out, rows.Err()
}
